-- El recorrido del Sábado de Pasión por calles (16-10-2026). La línea es la
-- buena (dibujada a mano por el usuario); los nombres de las paradas no
-- cuadraban con ella (venían del itinerario de partida). Ahora la lista de al
-- lado del mapa son las calles por las que va la línea, en orden: cada una
-- empieza en una esquina del trazado, nombrada con el mapa del barrio y
-- corregida por el usuario (Juan Gris es Obsidiana, que la paralela no se usa;
-- Ciudad de Andújar es solo una esquina; los dos pasos de la avenida, cruces).
-- Las horas se reparten entre la salida (18:00) y la entrada (00:00), con 10
-- minutos parados en la peña de C. Río Duratón para las saetas, que es el
-- único sitio de interés.
--
-- Y dos retoques de la línea que pidió al verla: al salir de la glorieta de
-- Obsidiana la esquina 10 estaba en la otra calzada (la línea saltaba de una a
-- otra) y pasa a la buena; y el cruce de la avenida entre C. Mijas y C.
-- Corregidor Ruiz de Pereda va recto (`rectos`), sin el zigzag por los pasos
-- de peatones. Se guardan las esquinas y la línea que salen de ellas.
--
-- Se toca solo si el itinerario sigue con las paradas de antes y la misma
-- línea (180 puntos): si alguien lo cambió en el CMS, se queda el suyo. El
-- historial no se toca. En otra instalación no casa nada y no hace nada.

UPDATE `ContenidoPagina`
SET `datos` = JSON_SET(`datos`,
  CONCAT(REPLACE(JSON_UNQUOTE(JSON_SEARCH(`datos`, 'one', 'itinerario', NULL, '$.bloques[*].tipo')), '.tipo', ''), '.paradas'), JSON_EXTRACT('[{"hora":"","lugar":"Peña de C. Río Duratón","enRuta":0.7356,"nota":"Saetas a la Virgen","minutos":10}]', '$'),
  CONCAT(REPLACE(JSON_UNQUOTE(JSON_SEARCH(`datos`, 'one', 'itinerario', NULL, '$.bloques[*].tipo')), '.tipo', ''), '.recorrido.esquinas'), JSON_EXTRACT('[[-4.449245,36.711928],[-4.449632,36.713287],[-4.452207,36.712779],[-4.451853,36.711876],[-4.452475,36.711713],[-4.453623,36.710534],[-4.45535,36.710165],[-4.45534,36.709674],[-4.455103,36.709562],[-4.455173,36.709217],[-4.455093,36.708608],[-4.453301,36.708978],[-4.449085,36.709691],[-4.448827,36.708763],[-4.448183,36.708883],[-4.448366,36.709537],[-4.446956,36.709791],[-4.446903,36.709688],[-4.446248,36.709812],[-4.446371,36.710182],[-4.447814,36.709924],[-4.447949,36.710462],[-4.447562,36.71053],[-4.447439,36.710995],[-4.447744,36.71108],[-4.447822,36.711316],[-4.447433,36.711381],[-4.447656,36.712129],[-4.448023,36.712062],[-4.448098,36.712363],[-4.449289,36.712155],[-4.449245,36.711928]]', '$'),
