  CONCAT(REPLACE(JSON_UNQUOTE(JSON_SEARCH(`datos`, 'one', 'itinerario', NULL, '$.bloques[*].tipo')), '.tipo', ''), '.recorrido.rectos'), JSON_EXTRACT('[23]', '$'),
